/*
 * Hanzi Flow — 01-data.js
 * Vocabulary, character and sentence tables.
 * The raw rows come from data/*.js (generated by tools/build_data.py); this file turns them
 * into the objects the rest of the app uses: W (all words), BY (lookup by hanzi), BY_LEVEL,
 * CH (character info), SENT (sentences) and a few constant tables (stage names, ranks).
 */
'use strict';

// ======== data ========
const DAY = 86400000,
  MIN = 60000;
const V = window.CF_VOCAB || [];
const W = V.map((r, i) => ({
  id: i,
  s: r[0],
  t: r[1],
  p: r[2],
  y: r[3],
  m: r[4],
  l: r[5],
  pos: r[6] || '',
  cl: r[7] || '',
}));
const BY = new Map(W.map((w) => [w.s, w]));
const CH = window.CF_CHARS || {};
const SENT = window.CF_SENTENCES || [];
const SENT_BY = new Map();
SENT.forEach((s, i) => {
  for (const w of s[4]) {
    if (!SENT_BY.has(w)) SENT_BY.set(w, []);
    SENT_BY.get(w).push(i);
  }
});
const LEVELS = [1, 2, 3, 4, 5, 6];
const BY_LEVEL = {};
LEVELS.forEach((l) => (BY_LEVEL[l] = W.filter((w) => w.l === l)));
const LV_IDX = new Map();
LEVELS.forEach((l) => BY_LEVEL[l].forEach((w, i) => LV_IDX.set(w.s, i)));
const SHARD = 1000;
const SHARDS = LEVELS.flatMap((l) =>
  Array.from(
    { length: Math.max(1, Math.ceil(BY_LEVEL[l].length / SHARD)) },
    (_, i) => 'l' + l + '-' + i,
  ),
);
function shardOf(w) {
  return 'l' + w.l + '-' + Math.floor((LV_IDX.get(w.s) || 0) / SHARD);
}
function slim(v) {
  const o = {
    s: v.s,
    e: Math.round(v.e * 100) / 100,
    i: Math.round(v.i * 100) / 100,
    d: Math.round(v.d),
    r: v.r,
    l: v.l,
    n: Math.round(v.n),
    k: v.k || 0,
  };
  if (v.sd != null) o.sd = Math.round(v.sd);
  return o;
}
